cd /workspace && cat > src/repository.ts <<'EOF'
import { Order } from './types';
const cmp = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);
export class OrderRepository {
  constructor(private readonly rows: Order[]) {}
  list(tenant: string, after?: { createdAt: string; id: string }): Order[] {
    return this.rows
      .filter(row => row.tenant === tenant)
      .filter(row => !after || cmp(row.createdAt, after.createdAt) > 0 ||
        (row.createdAt === after.createdAt && cmp(row.id, after.id) > 0))
      .sort((a, b) => cmp(a.createdAt, b.createdAt) || cmp(a.id, b.id));
  }
}
EOF
cat > src/handler.ts <<'EOF'
import { OrderRepository } from './repository';
import { ListRequest, Page } from './types';
export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}
  list(request: ListRequest): Page {
    if (!request.tenant || !Number.isInteger(request.limit) || request.limit < 1 || request.limit > 100) {
      throw new Error('invalid request');
    }
    let after: { createdAt: string; id: string } | undefined;
    if (request.cursor !== undefined) {
      if (typeof request.cursor !== 'string') throw new Error('invalid request');
      const parts = request.cursor.split('|');
      if (parts.length !== 2 || !parts[0] || !parts[1]) throw new Error('invalid request');
      after = { createdAt: parts[0], id: parts[1] };
    }
    const rows = this.repository.list(request.tenant, after);
    const items = rows.slice(0, request.limit);
    const last = items[items.length - 1];
    const nextCursor = rows.length > items.length && last ? last.createdAt + '|' + last.id : null;
    return { items, nextCursor };
  }
}
EOF
cat >> checks/public.cjs <<'EOF'

const h2 = new OrderHandler(new OrderRepository([
  { id: 'b', tenant: 'a', createdAt: '1', total: 1 },
  { id: 'a', tenant: 'a', createdAt: '1', total: 1 },
  { id: 'z', tenant: 'o', createdAt: '1', total: 1 },
  { id: 'c', tenant: 'a', createdAt: '2', total: 1 }
]));
const p1 = h2.list({ tenant: 'a', limit: 2 });
assert.deepEqual(p1.items.map(x => x.id), ['a', 'b']);
assert.equal(p1.nextCursor, '1|b');
const p2 = h2.list({ tenant: 'a', limit: 2, cursor: p1.nextCursor });
assert.deepEqual(p2.items.map(x => x.id), ['c']);
assert.equal(p2.nextCursor, null);
assert.deepEqual(h2.list({ tenant: 'a', limit: 5, cursor: '1|z' }).items.map(x => x.id), ['c']);
for (const cursor of ['', '1', '1|', '|a', '1|a|b']) assert.throws(() => h2.list({ tenant: 'a', limit: 1, cursor }), /invalid request/);
EOF
tsc -p tsconfig.json && node checks/public.cjs && echo ok

